def skeleton(inputs):
    # Frozen fail-closed exact-rational skeleton: pure function, no I/O.
    required = ['F_definition', 'route_thesis_witnesses', 'duality_lemma_Rk_witnesses']
    for k in required:
        if k not in inputs:
            return (1, None)  # malformed input: fail closed
    missing = sorted(k for k in required if not inputs[k])
    if missing:
        return (3, missing)  # deterministic abort on missing definition/witnesses
    return (0, None)

REQUIRED = ['F_definition', 'route_thesis_witnesses', 'duality_lemma_Rk_witnesses']

WITNESS = {
    'skeleton_id': 'R005-L1-failclosed-skeleton',
    'arithmetic': 'exact integer/Fraction only',
    'inputs_present': {
        'F_definition': False,
        'route_thesis_witnesses': False,
        'duality_lemma_Rk_witnesses': False
    },
    'expected_exit_code': 3
}

def verify():
    w = WITNESS
    if w.get('skeleton_id') != 'R005-L1-failclosed-skeleton':
        return False
    if w.get('arithmetic') != 'exact integer/Fraction only':
        return False
    if w.get('expected_exit_code') != 3:
        return False
    inp = w.get('inputs_present')
    if not isinstance(inp, dict):
        return False
    # Property 1: as frozen (inputs absent), skeleton aborts deterministically, exit 3.
    code, abort_set = skeleton(inp)
    if code != 3 or abort_set is None:
        return False
    missing = sorted(k for k in REQUIRED if not inp[k])
    if abort_set != missing or not missing:
        return False
    # Property 2: determinism under re-execution.
    if skeleton(inp) != (code, abort_set):
        return False
    # Property 3: abort set is never empty (fail closed).
    if abort_set == []:
        return False
    # Property 4: with all inputs present the skeleton emits no mathematical claim
    # (exit 0, no abort) — the skeleton alone never certifies mathematics.
    full = {k: True for k in REQUIRED}
    c3, a3 = skeleton(full)
    if c3 != 0 or a3 is not None:
        return False
    # Property 5: any single falsy required input triggers abort 3 naming exactly it.
    for k in REQUIRED:
        probe = dict(full)
        probe[k] = False
        c4, a4 = skeleton(probe)
        if c4 != 3 or a4 != [k]:
            return False
    return True

RESULT = verify()
